-- Add 11 new CSMT platform starters (PF-8..PF-18) on the DN TH line. Parallel
-- platform signals; appear in CSMT_ML_KR/MMR, CSMT_SUB_ML, KYN_GOODS, KYN_SUB
-- via the shared CSMT_KYN_DN_TH section (rows 508-588, after CSMT S-7 / before S-45).
-- Additive; local then prod. Re-run magnet backfill after (magnet_id starts NULL).


-- book rows in CSMT_KYN_DN_TH

SELECT sg.signal_number, sg.placement, sg.is_rhs, sg.is_lhs, sg.ri_left_arms, sg.ri_right_arms, r.row_order, r.display_location
FROM div_signals sg JOIN div_signal_book_rows r ON r.signal_id=sg.id
WHERE sg.signal_number LIKE 'CSMT S-1%' AND sg.line='DN TH' AND CAST(SUBSTRING_INDEX(sg.signal_number,'-',-1) AS UNSIGNED) BETWEEN 8 AND 18
ORDER BY r.row_order;
